unsigned char data_A = 0xAF;
unsigned char data_B = 0x3C;
unsigned char data_C = 0x81;

// Calculate Parity byte (P)
unsigned char P = data_A ^ data_B ^ data_C;
// P = 0xAF ^ 0x3C ^ 0x81 => 0x52

// Data array representation (e.g., RAID 5)
unsigned char disk_data[3] = {data_A, data_B, data_C};
unsigned char calculated_P = 0;

for (int i = 0; i < 3; ++i) {
    calculated_P ^= disk_data[i];
}
// calculated_P == P (0x52)
